const loginForm=document.getElementById("login-form"),loginButton=document.getElementById("login-button"),loginMessage=document.getElementById("login-message"),loginInput=document.getElementById("id_magalu"),existingSession=window.magaluApi.readStoredUser();function setMessage(e,t){loginMessage.textContent=e,loginMessage.className=`form-message ${t}`}function setLoginButtonState({disabled:e,label:t,busy:o=!1}){loginButton.disabled=e,o?loginButton.setAttribute("aria-busy","true"):loginButton.removeAttribute("aria-busy");const n=loginButton.querySelector(".auth-mobile-primary-label");n?n.textContent=t:loginButton.textContent=t}existingSession&&window.location.replace(window.magaluApi.getAuthenticatedHomeUrl(existingSession)),loginForm.addEventListener("submit",async e=>{e.preventDefault();const t=loginInput.value.trim();if(t){setLoginButtonState({disabled:!0,label:"Entrando...",busy:!0}),setMessage("","");try{const e=await fetch(window.magaluApi.buildApiUrl("/api/auth/login"),window.magaluApi.withApiDefaults({method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id_magalu:t})})),o=await window.magaluApi.parseApiResponse(e);if(!e.ok)throw new Error(o.error||"Nao foi possivel efetuar o login.");window.magaluApi.storeUser(o.user),setMessage("Login efetuado. Redirecionando...","success"),window.setTimeout(()=>{window.location.href=window.magaluApi.getAuthenticatedHomeUrl(o.user)},400)}catch(e){setMessage(e.message,"error"),setLoginButtonState({disabled:!1,label:"Acessar",busy:!1})}}else setMessage("Informe o ID Magalu para entrar.","error")});